#include <bits/stdc++.h>
using namespace std;

class FenwickMax {
    vector<int> tree;

public:
    explicit FenwickMax(int n) : tree(n + 1, 0) {}

    void update(int index, int value) {
        for (int i = index; i < (int)tree.size(); i += i & -i)
            tree[i] = max(tree[i], value);
    }

    int query(int index) const {
        int result = 0;
        for (int i = index; i > 0; i -= i & -i)
            result = max(result, tree[i]);
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> diff(m + 2, 0);
    for (int i = 0; i < n; ++i) {
        int l, r;
        cin >> l >> r;
        ++diff[l];
        --diff[r + 1];
    }

    vector<int> count(m + 1);
    for (int i = 1; i <= m; ++i)
        count[i] = count[i - 1] + diff[i];

    vector<int> increasingEnd(m + 1);
    vector<int> decreasingStart(m + 2);
    vector<int> prefixBest(m + 1, 0);
    vector<int> suffixBest(m + 2, 0);

    FenwickMax leftTree(n + 1);
    for (int i = 1; i <= m; ++i) {
        int index = count[i] + 1;
        increasingEnd[i] = leftTree.query(index) + 1;
        leftTree.update(index, increasingEnd[i]);
        prefixBest[i] = max(prefixBest[i - 1], increasingEnd[i]);
    }

    FenwickMax rightTree(n + 1);
    for (int i = m; i >= 1; --i) {
        int index = count[i] + 1;
        decreasingStart[i] = rightTree.query(index) + 1;
        rightTree.update(index, decreasingStart[i]);
        suffixBest[i] = max(suffixBest[i + 1], decreasingStart[i]);
    }

    int answer = 0;

    for (int p = 1; p <= m; ++p) {
        answer = max(answer, prefixBest[p - 1] + suffixBest[p + 1]);

        if (count[p] > 0) {
            answer = max(answer,
                         increasingEnd[p] + decreasingStart[p] - 1);
        }
    }

    cout << answer << '\n';
    return 0;
}

